INSERT INTO finding (id, reference, cve, project_id, package_name, package_group, installed_version, fixed_version, ecosystem, title, description, cvss_vector, cvss_score, cwe, stage, tool, status, detected_at, status_changed_at) VALUES
    ('10000000-0000-0000-0000-000000000001', 'F-1101', 'CVE-2025-29927', '00000000-0000-0000-0000-000000000001', 'next', NULL, '14.2.10', '14.2.25', 'NPM', 'Authorization bypass in Next.js middleware', 'Next.js is a React framework for building full-stack web applications. It is possible to bypass authorization checks within a Next.js application if the authorization check occurs in middleware, by sending a crafted x-middleware-subrequest header.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N', 9.1, 'CWE-285', 'SCA', 'Trivy', 'OPEN', '2026-10-15T06:00:00Z', '2026-10-15T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000002', 'F-1102', 'CVE-2024-47875', '00000000-0000-0000-0000-000000000001', 'dompurify', NULL, '3.1.2', '3.1.3', 'NPM', 'Nesting-based mutation XSS in DOMPurify', 'DOMPurify is a DOM-only, super-fast, uber-tolerant XSS sanitizer for HTML, MathML and SVG. DOMPurify was vulnerable to nesting-based mutation XSS (mXSS), allowing crafted markup to bypass sanitization.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:C/C:H/I:H/A:H', 10, 'CWE-79', 'SCA', 'Trivy', 'OPEN', '2026-10-15T06:00:00Z', '2026-10-15T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000003', 'F-1103', 'CVE-2024-45296', '00000000-0000-0000-0000-000000000001', 'path-to-regexp', NULL, '0.1.7', '0.1.10', 'NPM', 'Regular expression denial of service in path-to-regexp', 'path-to-regexp turns path strings into regular expressions. In certain cases, path-to-regexp outputs a regular expression that can be exploited to cause poor performance, because JavaScript is single threaded and regex matching runs on the main thread. Routes containing two parameters within a single segment separated by something that is not a period are affected.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:H', 7.5, 'CWE-1333', 'SCA', 'Trivy', 'OPEN', '2026-10-14T06:00:00Z', '2026-10-14T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000004', 'F-1104', 'CVE-2024-43788', '00000000-0000-0000-0000-000000000001', 'webpack', NULL, '5.93.0', '5.94.0', 'NPM', 'DOM clobbering gadget in webpack AutoPublicPathRuntimeModule', 'Webpack is a module bundler. A DOM clobbering gadget in the AutoPublicPathRuntimeModule can lead to cross-site scripting in websites where attacker-controlled HTML elements, such as img tags with an unsanitized name attribute, are present.', 'CVSS:3.1/AV:N/AC:H/PR:N/UI:R/S:C/C:L/I:L/A:L', 6.4, 'CWE-79', 'SCA', 'Trivy', 'TRIAGED', '2026-10-12T06:00:00Z', '2026-10-13T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000005', 'F-1105', 'CVE-2024-4067', '00000000-0000-0000-0000-000000000001', 'micromatch', NULL, '4.0.5', '4.0.8', 'NPM', 'Regular expression denial of service in micromatch', 'The NPM package micromatch is vulnerable to Regular Expression Denial of Service (ReDoS). The vulnerability occurs in micromatch.braces() due to greedy matching of a pattern; supplying a malicious payload makes the function hang.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:L', 5.3, 'CWE-1333', 'SCA', 'Trivy', 'FALSE_POSITIVE', '2026-10-10T06:00:00Z', '2026-10-10T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000006', 'F-1106', 'CVE-2024-52798', '00000000-0000-0000-0000-000000000001', 'path-to-regexp', NULL, '0.1.10', '0.1.12', 'NPM', 'Incomplete fix for path-to-regexp ReDoS', 'The regular expression generated for routes with multiple parameters in a single segment was still vulnerable to backtracking after the fix for CVE-2024-45296, allowing a denial of service with crafted URLs.', 'CVSS:3.1/AV:N/AC:H/PR:N/UI:N/S:U/C:N/I:N/A:H', 5.9, 'CWE-1333', 'SCA', 'Trivy', 'FIXED', '2026-10-09T06:00:00Z', '2026-10-14T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000007', 'F-1107', 'CVE-2023-44270', '00000000-0000-0000-0000-000000000001', 'postcss', NULL, '8.4.24', '8.4.31', 'NPM', 'Line return parsing error in PostCSS', 'An issue was discovered in PostCSS before 8.4.31. The vulnerability affects linters using PostCSS to parse external untrusted CSS. An attacker can prepare CSS so that it is parsed by PostCSS as a comment but included in the output as a CSS node.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:N', 5.3, 'CWE-74', 'SCA', 'Trivy', 'ACCEPTED', '2026-10-02T06:00:00Z', '2026-10-05T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000008', 'F-1201', 'CVE-2025-24813', '00000000-0000-0000-0000-000000000002', 'tomcat-embed-core', 'org.apache.tomcat.embed', '10.1.30', '10.1.35', 'MAVEN', 'Remote code execution via partial PUT in Apache Tomcat', 'Path equivalence (internal dot) in Apache Tomcat allows remote code execution, information disclosure or malicious content to be added to uploaded files via write-enabled Default Servlet when partial PUT support and file-based session persistence are enabled.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H', 9.8, 'CWE-44', 'SCA', 'OWASP Dependency-Check', 'OPEN', '2026-10-13T06:00:00Z', '2026-10-13T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000009', 'F-1202', 'CVE-2024-38821', '00000000-0000-0000-0000-000000000002', 'spring-security-web', 'org.springframework.security', '6.3.3', '6.3.4', 'MAVEN', 'Authorization bypass of static resources in Spring Security', 'Spring WebFlux applications that have Spring Security authorization rules on static resources can be bypassed under certain circumstances, giving unauthenticated access to protected static resources.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N', 9.1, 'CWE-285', 'SCA', 'OWASP Dependency-Check', 'OPEN', '2026-10-13T06:00:00Z', '2026-10-13T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000010', 'F-1203', 'CVE-2024-45490', '00000000-0000-0000-0000-000000000002', 'libexpat1', NULL, '2.5.0-1', '2.5.0-1+deb12u1', 'DEBIAN', 'Negative length handling in libexpat XML_ParseBuffer', 'An issue was discovered in libexpat before 2.6.3. xmlparse.c does not reject a negative length for XML_ParseBuffer, which may lead to memory corruption.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H', 9.8, 'CWE-611', 'IMAGE', 'Trivy', 'OPEN', '2026-10-13T06:00:00Z', '2026-10-13T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000011', 'F-1204', 'CVE-2024-38816', '00000000-0000-0000-0000-000000000002', 'spring-webmvc', 'org.springframework', '6.1.12', '6.1.13', 'MAVEN', 'Path traversal in Spring Framework functional web frameworks', 'Applications serving static resources through the functional web frameworks WebMvc.fn or WebFlux.fn are vulnerable to path traversal attacks. An attacker can craft malicious HTTP requests and obtain any file on the file system that is also accessible to the process.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N', 7.5, 'CWE-22', 'SCA', 'OWASP Dependency-Check', 'TRIAGED', '2026-10-11T06:00:00Z', '2026-10-12T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000012', 'F-1205', 'CVE-2024-7254', '00000000-0000-0000-0000-000000000002', 'protobuf-java', 'com.google.protobuf', '3.25.3', '3.25.5', 'MAVEN', 'Stack overflow parsing nested groups in protobuf-java', 'Parsing untrusted Protocol Buffers data containing an arbitrary number of nested groups, or series of SGROUP tags, can corrupt the stack by exceeding the stack limit, leading to a denial of service.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:H', 7.5, 'CWE-674', 'SCA', 'OWASP Dependency-Check', 'OPEN', '2026-10-11T06:00:00Z', '2026-10-11T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000013', 'F-1206', 'CVE-2022-1471', '00000000-0000-0000-0000-000000000002', 'snakeyaml', 'org.yaml', '1.33', '2.0', 'MAVEN', 'Unsafe deserialization in SnakeYAML Constructor', 'SnakeYAML''s Constructor() class does not restrict types which can be instantiated during deserialization. Deserializing YAML content provided by an attacker can lead to remote code execution.', 'CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:C/C:L/I:L/A:L', 8.3, 'CWE-502', 'SCA', 'OWASP Dependency-Check', 'FALSE_POSITIVE', '2026-10-09T06:00:00Z', '2026-10-09T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000014', 'F-1207', 'CVE-2024-38808', '00000000-0000-0000-0000-000000000002', 'spring-expression', 'org.springframework', '6.1.10', '6.1.14', 'MAVEN', 'Denial of service via crafted SpEL expression', 'Applications that evaluate user-supplied Spring Expression Language (SpEL) expressions are vulnerable to a denial of service caused by a specially crafted expression.', 'CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:U/C:N/I:N/A:L', 4.3, 'CWE-770', 'SCA', 'OWASP Dependency-Check', 'TRIAGED', '2026-10-08T06:00:00Z', '2026-10-09T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000015', 'F-1208', 'CVE-2023-6378', '00000000-0000-0000-0000-000000000002', 'logback-classic', 'ch.qos.logback', '1.4.11', '1.4.12', 'MAVEN', 'Serialization vulnerability in logback receiver', 'A serialization vulnerability in the logback receiver component allows an attacker to mount a denial-of-service attack by sending poisoned data. This requires the logback-receiver component to be enabled and reachable by the attacker.', 'CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:U/C:N/I:L/A:H', 7.1, 'CWE-502', 'SCA', 'OWASP Dependency-Check', 'FIXED', '2026-10-01T06:00:00Z', '2026-10-06T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000016', 'F-1301', 'CVE-2025-27789', '00000000-0000-0000-0000-000000000003', '@babel/runtime', NULL, '7.24.0', '7.26.10', 'NPM', 'Inefficient RegExp complexity in Babel named capturing groups', 'When using Babel to compile regular expression named capturing groups, Babel generates a polyfill for the .replace method that has quadratic complexity on some specific replacement pattern strings.', 'CVSS:3.1/AV:N/AC:H/PR:N/UI:N/S:U/C:N/I:N/A:H', 6.2, 'CWE-1333', 'SCA', 'Trivy', 'OPEN', '2026-10-12T06:00:00Z', '2026-10-12T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000017', 'F-1302', 'CVE-2024-45296', '00000000-0000-0000-0000-000000000003', 'path-to-regexp', NULL, '0.1.7', '0.1.10', 'NPM', 'Regular expression denial of service in path-to-regexp', 'path-to-regexp turns path strings into regular expressions. In certain cases, path-to-regexp outputs a regular expression that can be exploited to cause poor performance, because JavaScript is single threaded and regex matching runs on the main thread. Routes containing two parameters within a single segment separated by something that is not a period are affected.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:H', 7.5, 'CWE-1333', 'SCA', 'Trivy', 'TRIAGED', '2026-10-12T06:00:00Z', '2026-10-12T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000018', 'F-1303', 'CVE-2024-21490', '00000000-0000-0000-0000-000000000003', 'angular', NULL, '1.8.3', NULL, 'NPM', 'ReDoS in AngularJS ng-srcset directive', 'All versions of the package angular are vulnerable to Regular Expression Denial of Service (ReDoS) via the ng-srcset directive, due to insecure regular expressions. AngularJS is end-of-life and will not receive a fix.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:H', 7.5, 'CWE-1333', 'SCA', 'Trivy', 'FALSE_POSITIVE', '2026-10-12T06:00:00Z', '2026-10-12T14:00:00Z'),
    ('10000000-0000-0000-0000-000000000019', 'F-1304', 'CVE-2024-47764', '00000000-0000-0000-0000-000000000003', 'cookie', NULL, '0.6.0', '0.7.0', 'NPM', 'Out-of-bounds characters accepted in cookie name, path and domain', 'The cookie name could be used to set other fields of the cookie, resulting in an unexpected cookie value, when user input is passed as the cookie name, path or domain.', 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:N', 5.3, 'CWE-74', 'SCA', 'Trivy', 'OPEN', '2026-10-11T06:00:00Z', '2026-10-11T06:00:00Z'),
    ('10000000-0000-0000-0000-000000000020', 'F-1305', 'CVE-2024-55565', '00000000-0000-0000-0000-000000000003', 'nanoid', NULL, '3.3.7', '3.3.8', 'NPM', 'Predictable results in nanoid with non-integer values', 'nanoid mishandles non-integer values: when 0.1 is given as the size argument, the generated IDs can be predictable.', 'CVSS:3.1/AV:N/AC:H/PR:N/UI:N/S:U/C:L/I:N/A:N', 3.7, 'CWE-835', 'SCA', 'Trivy', 'OPEN', '2026-10-07T06:00:00Z', '2026-10-07T06:00:00Z');
